    ok = ok && !d.DoAmbush && !d.TricksterKilledBeforeAmbush && d.Frame == 4;
    std::printf(ok ? "00e2f170_TEST PASS\n" : "00e2f170_TEST FAIL\n");
    return ok ? 0 : 1;
}
